<article class="mapr-card"><a class="mapr-card__image" href="<?php echo esc_url($product->url); ?>"><?php echo wp_kses_post($product->image); ?></a><div class="mapr-card__body"><?php if($product->family): ?><span class="mapr-card__family"><?php echo esc_html($product->family); ?></span><?php endif; ?><h2><a href="<?php echo esc_url($product->url); ?>"><?php echo esc_html($product->title); ?></a></h2><div class="mapr-price"><?php echo wp_kses_post($product->price_html); ?></div><div class="mapr-stock"><?php echo wp_kses_post($product->stock_html); ?></div><?php if($product->warning): ?><div class="mapr-warning"><strong>Controleer je product-/servicenummer</strong><span><?php echo esc_html(sprintf('Dit onderdeel past alleen op bepaalde uitvoeringen van %s %s.',$view->model['brand'],$view->model['commercial_type'])); ?></span></div><?php endif; ?><div class="mapr-card__actions"><a class="mapr-product-link" href="<?php echo esc_url($product->url); ?>">Bekijk product <span aria-hidden="true">→</span></a><?php if($product->purchasable): ?><a class="mapr-cart" href="<?php echo esc_url($product->add_url); ?>" rel="nofollow" aria-label="<?php echo esc_attr($product->add_text); ?>"><span aria-hidden="true">🛒</span><span class="mapr-cart__label"><?php echo esc_html($product->add_text); ?></span></a><?php endif; ?></div></div></article>
